readonly record struct Step(int? Value, Func<Step>? More);

static Step Even(int n) => n == 0 ? new(1, null) : new(null, () => Odd(n - 1));
static Step Odd(int n)  => n == 0 ? new(0, null) : new(null, () => Even(n - 1));

static int Run(Step s) {
    while (s.More is not null) s = s.More();   // one frame for the whole recursion
    return s.Value!.Value;
}
